import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Transport","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/transport.md","filePath":"03-developer/models/transport.md"}`),a={name:`03-developer/models/transport.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to “Transport”">​</a></h1><p>The <code>Transport</code> model is used to manage product shipping methods, such as postal delivery or motorcycle courier. Each shipping method has a title, description, cost, icon, and settings for display order and default selection.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique ID of the shipping method</td></tr><tr><td><code>title</code></td><td>TEXT</td><td>No</td><td>Shipping method title; translatable</td></tr><tr><td><code>description</code></td><td>TEXT</td><td>Yes</td><td>Shipping method description; translatable</td></tr><tr><td><code>sort</code></td><td>INT UNSIGNED</td><td>No</td><td>Shipping method display order; defaults to <code>0</code></td></tr><tr><td><code>is_default</code></td><td>TINYINT(1)</td><td>No</td><td>Indicates whether this is the default shipping method; defaults to <code>0</code></td></tr><tr><td><code>price</code></td><td>DECIMAL(20,2)</td><td>No</td><td>Shipping cost; defaults to <code>0.00</code></td></tr><tr><td><code>icon</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Shipping method icon name from Remix Icon</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record soft deletion time</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record last update time</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>title</code> and <code>description</code> fields are defined as translatable, allowing the shipping method&#39;s title and description to be displayed in different languages.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>The title can be the name of a shipping method, such as &quot;Postal delivery&quot; or &quot;Motorcycle courier.&quot;</li><li>The <code>sort</code> field is used to set the display order of shipping methods.</li><li>The <code>is_default</code> field specifies which shipping method is selected by default.</li><li><strong>When a new shipping method is selected as the default, the previous default shipping method must be unset as the default and its <code>is_default</code> value changed to <code>0</code> (<code>false</code>).</strong> This behavior must be handled in the application logic; the table structure alone does not ensure that there is only one default method.</li><li>The <code>price</code> field stores the shipping cost with two decimal places of precision.</li><li>The <code>icon</code> field is intended for selecting an icon through an Icon Picker using the Remix Icon collection.</li><li>The <code>deleted_at</code> field is intended to record the soft deletion time; whether Soft Deletes are enabled depends on the model configuration.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};